# Hypothesis: TypeIs narrowing of a tuple parameter still applies when the check runs inside a nested function that closes over the outer parameter.
from typing import TypeIs, reveal_type


def is_tuple_of_strings(v: tuple[int | str, ...]) -> TypeIs[tuple[str, ...]]:
    return all(isinstance(x, str) for x in v)


def outer(t: tuple[int | str, int | str]) -> str:
    def inner() -> str:
        if is_tuple_of_strings(t):
            reveal_type(t)
            return ''.join(t)
        reveal_type(t)
        return 'mixed'

    return inner()


def outer_mixed(t: tuple[str, int]) -> str:
    def inner() -> str:
        if is_tuple_of_strings(t):
            reveal_type(t)
            return 'never'
        reveal_type(t)
        return 'tuple[str, int]'

    return inner()


print(outer(('a', 'b')), outer((1, 'b')))
print(outer_mixed(('s', 2)))
